//! Fresh descriptor-owned metadata; every generated byte is sealed, never exempted.

use aros_common::{sha256_bytes, sha256_reader, CancellationToken};
use rustix::fs::{self as fs, Mode, OFlags};
use std::{
    fs::File,
    io::{Read as _, Write as _},
    path::{Path, PathBuf},
    time::Instant,
};

use super::super::unix::{identity, parent};
use crate::{
    filesystem::{open_directory, DIRECTORY},
    inspection,
    recipe::GitObjectId,
    source_audit::{
        material::{Entry, Inventory},
        worktree, Budget, MAX_INVENTORY_BYTES,
    },
    ContractError,
};

const CONFIG: &[u8] = b"[core]\nrepositoryformatversion = 0\nbare = false\nfilemode = true\nlogallrefupdates = false\n";

pub(super) struct Store {
    pub root: PathBuf,
    pub deadline: Instant,
    pub cancellation: CancellationToken,
    root_file: File,
    file: File,
    root_id: (u64, u64),
    id: (u64, u64),
    entries: Inventory,
}

impl Store {
    pub fn create(
        root: &Path,
        commit: &GitObjectId,
        deadline: Instant,
        cancellation: &CancellationToken,
    ) -> Result<Self, ContractError> {
        Budget::controlled(deadline, cancellation).check(0)?;
        let root_file = open_directory(root).map_err(io_failure)?;
        let root_id = identity(&root_file)?;
        fs::mkdirat(&root_file, ".git", Mode::from_raw_mode(0o700)).map_err(io_failure)?;
        let file = File::from(
            fs::openat(&root_file, ".git", DIRECTORY, Mode::empty()).map_err(io_failure)?,
        );
        let id = identity(&file)?;
        let mut store = Self {
            root: root.to_owned(),
            deadline,
            cancellation: cancellation.clone(),
            root_file,
            file,
            root_id,
            id,
            entries: Inventory::new(),
        };
        for name in ["objects", "objects/pack", "refs"] {
            let (ancestor, leaf) = parent(&store.file, name)?;
            fs::mkdirat(&ancestor, leaf, Mode::from_raw_mode(0o700)).map_err(io_failure)?;
            store.entries.insert(name.into(), directory());
        }
        store.write("config", CONFIG)?;
        let head = format!("{}\n", commit.as_str());
        store.write("HEAD", head.as_bytes())?;
        store.write("shallow", head.as_bytes())?;
        store.check()?;
        Ok(store)
    }

    fn write(&mut self, name: &str, bytes: &[u8]) -> Result<(), ContractError> {
        let (ancestor, leaf) = parent(&self.file, name)?;
        let mut file = File::from(
            fs::openat(
                &ancestor,
                leaf,
                OFlags::WRONLY | OFlags::CREATE | OFlags::EXCL | OFlags::NOFOLLOW | OFlags::CLOEXEC,
                Mode::from_raw_mode(0o600),
            )
            .map_err(io_failure)?,
        );
        file.write_all(bytes).map_err(io_failure)?;
        self.entries.insert(
            name.into(),
            Entry {
                mode: "100644",
                size: bytes.len(),
                digest: Some(sha256_bytes(bytes)),
            },
        );
        Ok(())
    }

    pub fn check(&self) -> Result<(), ContractError> {
        if identity(&self.root_file)? != self.root_id
            || identity(&open_directory(&self.root).map_err(io_failure)?)? != self.root_id
            || identity(&self.file)? != self.id
            || identity(&open_directory(&self.root.join(".git")).map_err(io_failure)?)? != self.id
        {
            return Err(ContractError::state(
                "isolated Git directory binding changed",
            ));
        }
        worktree::verify_material(
            &self.root.join(".git"),
            &self.entries,
            &mut Budget::controlled(self.deadline, &self.cancellation),
        )
    }

    pub fn git(&self, args: &[&str], input: &[u8], limit: usize) -> Result<Vec<u8>, ContractError> {
        self.check()?;
        inspection::prepare_git(
            &self.root,
            args,
            input,
            limit,
            self.deadline,
            &self.cancellation,
        )
    }

    pub fn import(&mut self, pack: &[u8]) -> Result<(), ContractError> {
        let max = format!("--max-input-size={}", pack.len());
        let output = self.git(
            &["index-pack", "--stdin", "--strict", "--threads=1", &max],
            pack,
            128,
        )?;
        let hash = std::str::from_utf8(&output)
            .ok()
            .and_then(|text| text.strip_prefix("pack\t"))
            .and_then(|text| text.strip_suffix('\n'))
            .ok_or_else(|| ContractError::identity("invalid isolated Git pack response"))?;
        let id = GitObjectId::try_from(hash.to_owned()).map_err(ContractError::identity)?;
        let stem = format!("objects/pack/pack-{}", id.as_str());
        let packed = format!("{stem}.pack");
        if self
            .entries
            .insert(
                packed,
                Entry {
                    mode: "100644",
                    size: pack.len(),
                    digest: Some(sha256_bytes(pack)),
                },
            )
            .is_some()
        {
            return Err(ContractError::identity(
                "isolated Git pack was unexpectedly repeated",
            ));
        }
        self.measure(&format!("{stem}.idx"))?;
        self.check()
    }

    pub fn index(&mut self, tree: &GitObjectId) -> Result<(), ContractError> {
        if !self
            .git(&["read-tree", tree.as_str()], &[], 1024)?
            .is_empty()
        {
            return Err(ContractError::identity(
                "unexpected isolated Git index response",
            ));
        }
        self.measure("index")?;
        self.check()
    }

    fn measure(&mut self, name: &str) -> Result<(), ContractError> {
        let (ancestor, leaf) = parent(&self.file, name)?;
        let mut file = File::from(
            fs::openat(
                &ancestor,
                leaf,
                OFlags::RDONLY | OFlags::NOFOLLOW | OFlags::NONBLOCK | OFlags::CLOEXEC,
                Mode::empty(),
            )
            .map_err(io_failure)?,
        );
        let stat = fs::fstat(&file).map_err(io_failure)?;
        if !fs::FileType::from_raw_mode(stat.st_mode).is_file()
            || stat.st_nlink != 1
            || stat.st_mode & 0o111 != 0
        {
            return Err(ContractError::state(
                "generated Git metadata must be a single-link nonexecutable regular file",
            ));
        }
        let measured = sha256_reader(&mut (&mut file).take(MAX_INVENTORY_BYTES as u64 + 1))
            .map_err(io_failure)?;
        if measured.size > MAX_INVENTORY_BYTES as u64 {
            return Err(ContractError::invalid("generated Git index exceeds 32 MiB"));
        }
        if self
            .entries
            .insert(
                name.into(),
                Entry {
                    mode: "100644",
                    size: measured.size as usize,
                    digest: Some(measured.digest),
                },
            )
            .is_some()
        {
            return Err(ContractError::state(
                "generated Git metadata unexpectedly already has a sealed identity",
            ));
        }
        Ok(())
    }

    pub fn seal(self, material: &mut Inventory, relative: &str) -> Result<(), ContractError> {
        self.check()?;
        let prefix = if relative.is_empty() {
            ".git".into()
        } else {
            format!("{relative}/.git")
        };
        if material.insert(prefix.clone(), directory()).is_some() {
            return Err(ContractError::identity(
                "Git metadata collides with raw source material",
            ));
        }
        for (path, entry) in self.entries {
            let path = format!("{prefix}/{path}");
            if path.len() > 4096 || material.insert(path, entry).is_some() {
                return Err(ContractError::identity(
                    "generated metadata path collides or exceeds 4096 bytes",
                ));
            }
        }
        Ok(())
    }
}

const fn directory() -> Entry {
    Entry {
        mode: "040000",
        size: 0,
        digest: None,
    }
}

pub(super) fn io_failure(error: impl Into<std::io::Error>) -> ContractError {
    ContractError::state(format!(
        "isolated Git metadata I/O failed ({:?}); partial material is retained",
        error.into().kind()
    ))
}
